/** Compose explicitly ordered owner fragments without replacing their schema objects. */
function composeProtocolSchemaFragments(fragments) {
	const registry = {};
	for (const fragment of fragments) for (const [key, schema] of Object.entries(fragment)) {
		if (Object.hasOwn(registry, key)) throw new Error(`Duplicate protocol schema key: ${key}`);
		registry[key] = schema;
	}
	return registry;
}
